begin;
do $$
declare a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();m uuid:=gen_random_uuid();
o1 uuid; o2 uuid; p1 uuid;p2 uuid; n uuid;ni uuid;d uuid;di uuid;b uuid;al uuid;sh uuid;k uuid:=gen_random_uuid();denied boolean;result_qty integer;
begin
insert into auth.users(id,email,raw_user_meta_data) values(a,a||'@example.test','{}'),(u,u||'@example.test','{"role":"admin"}'),(v,v||'@example.test','{}'),(m,m||'@example.test','{}');
if exists(select 1 from public.user_roles where user_id=u and role='admin') then raise exception 'FAIL metadata escalates role';end if;
insert into public.user_roles(user_id,role) values(a,'admin'),(v,'relawan'),(m,'mitra');
insert into public.organizations(name,kind,verified) values('Test source','social_institution',true) returning id into o1;
insert into public.organizations(name,kind,verified) values('Test recipient','disaster_post',true) returning id into o2;
insert into public.organization_members(organization_id,user_id) values(o2,m);
insert into public.collection_points(organization_id,name,public_address) values(o1,'Test source point','Simulation') returning id into p1;
insert into public.collection_points(organization_id,name,public_address) values(o2,'Test destination','Simulation') returning id into p2;
insert into public.needs(organization_id,point_id,title,deadline_at,status) values(o2,p2,'Test need',now()+interval '1 day','open') returning id into n;
insert into public.need_items(need_id,category,size_code,age_group,requested_qty) values(n,'shirt','M','adult',8) returning id into ni;
insert into public.donations(donor_id,point_id,status) values(u,p1,'received') returning id into d;
insert into public.donation_items(donation_id,category,size_code,age_group,quantity) values(d,'shirt','M','adult',10) returning id into di;
perform set_config('request.jwt.claim.sub',u::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
perform set_config('role','authenticated',true);
if (select count(*) from public.profiles)<>1 then raise exception 'FAIL profile leakage';end if;
denied:=false;begin perform public.admin_set_role(u,'admin',true);exception when insufficient_privilege then denied:=true;end;
if not denied then raise exception 'FAIL self grant';end if;
denied:=false;begin insert into public.user_roles(user_id,role) values(u,'admin');exception when insufficient_privilege then denied:=true;end;
if not denied then raise exception 'FAIL direct role write';end if;
if not exists(select 1 from public.donations where id=d) then raise exception 'FAIL donor visibility';end if;
denied:=false;begin perform public.record_inspection(di,8,2,'Damaged');exception when insufficient_privilege then denied:=true;end;
if not denied then raise exception 'FAIL donor curate';end if;
perform set_config('request.jwt.claim.sub',v::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);
if exists(select 1 from public.donations where id=d) then raise exception 'FAIL unassigned volunteer leak';end if;
perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
b:=public.record_inspection(di,8,2,'Damaged');
if (select on_hand_qty from public.inventory_batches where id=b)<>8 then raise exception 'FAIL curated count';end if;
al:=public.reserve_allocation(b,ni,6,k);
if public.reserve_allocation(b,ni,6,k)<>al then raise exception 'FAIL idempotency';end if;
denied:=false;begin perform public.reserve_allocation(b,ni,3,gen_random_uuid());exception when others then if sqlerrm='Insufficient stock or need' then denied:=true;else raise;end if;end;
if not denied then raise exception 'FAIL oversubscribe';end if;
sh:=public.create_shipment(al,v);
perform set_config('request.jwt.claim.sub',v::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);
perform public.dispatch_shipment(sh);perform public.dispatch_shipment(sh);
denied:=false;begin perform public.confirm_receipt(sh,6,0,0);exception when insufficient_privilege then denied:=true;end;
if not denied then raise exception 'FAIL volunteer confirms receipt';end if;
perform set_config('request.jwt.claim.sub',m::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',m,'role','authenticated')::text,true);
perform public.confirm_receipt(sh,6,0,0);perform public.confirm_receipt(sh,6,0,0);
if not exists(select 1 from public.shipments where id=sh and status='received') then raise exception 'FAIL receipt';end if;
perform set_config('role','postgres',true);
select on_hand_qty into result_qty from public.inventory_batches where id=b;
if result_qty<>2 then raise exception 'FAIL stock count';end if;
if (select sum(received_good) from public.shipment_items where shipment_id=sh)<>6 then raise exception 'FAIL delivered impact';end if;
if (select count(*) from public.recycling_referrals rr join public.inspections ii on ii.id=rr.inspection_id where ii.item_id=di and rr.quantity=2)<>1 then raise exception 'FAIL recycling referral';end if;
perform set_config('pk.test_result','PASS: signup default role; metadata escalation blocked; own profile/donation isolation; direct role write denied; admin RPC escalation denied; donor curate denied; unassigned volunteer denied; curation 8/2; reserve idempotent; oversubscription rejected; dispatch idempotent; volunteer receipt denied; recipient receipt idempotent; stock=2; impact=6; referral=2',true);
end$$;
select current_setting('pk.test_result') as result;
rollback;

